import numpy as np
from scipy.optimize import least_squares
f=260.136;h=5.1;cy=72;cx=128
t=np.arctan((cy-h)/f);ct=np.cos(t);st=np.sin(t)
def ground(u,v):
 vv=(v-cy)/f
 D=(ct-vv*st)/(vv*ct+st)
 return np.array([(u-cx)/f*(D*ct+st),D])
def proj(P,z=0):
 x,d=P; zc=d*ct+(1-z)*st
 return np.array([cx+f*x/zc,cy+f*((1-z)*ct-d*st)/zc])
pts=[]
for a in np.linspace(0,2*np.pi,64,endpoint=False):
 x=150.1+17.95*np.cos(a);y=141.3+17.95*np.sin(a)
 if y<142:pts.append([x,y])
pts=np.array(pts);rays=np.c_[(pts[:,0]-cx)/f,(pts[:,1]-cy)/f,np.ones(len(pts))]
def cam(X,D,r):return np.array([X,(1-r)*ct-D*st,D*ct+(1-r)*st])
def error(p):
 C=cam(*p)
 return np.linalg.norm(np.cross(C,rays),axis=1)/np.linalg.norm(rays,axis=1)-p[2]
res=least_squares(error,[.15,1.5,.12]);X,D,r=res.x
print('initial',res.x,proj([X,D],r),proj([X,D]),error(res.x).std())
K=ground(123,85);P=np.array([X,D]);length=np.linalg.norm(K-P);unit=(K-P)/length
print('k',K,'source',P,'len',length)
for Kr in [.2,.25,.3,.4]:
 end=K-unit*(Kr+r)
 print('Kradius',Kr,'end',end,'contact',proj(end),'center',proj(end,r),'pixelradius',f*r/cam(*end,r)[2])
A=ground(142,72.4);B=ground(250,98.5);n=np.array([B[1]-A[1],A[0]-B[0]]);n/=np.linalg.norm(n)
print('mirror',A,B,n)
for frac in [0,.2,.4,.6,.8,1]:
 end=K-unit*(.25+r);Q=P+(end-P)*frac;RQ=Q-2*n*np.dot(Q-A,n)
 print(frac,proj(Q,r),proj(RQ,r),f*r/cam(*RQ,r)[2])
